# Cannabis (weed) city rankings by region — sourced, hedged, citable.
# Method note carried on every page: no country measures weed use per city
# directly. Rankings combine the best available proxies per region (wastewater
# THC-COOH analysis, national surveys, dispensary counts, treatment data).
# They are directional, not precise league tables.

WEED_CITY_PAGES = [
 dict(slug="weed-cities-usa", region="United States", title="Top 10 US cities with the most weed use",
  updated="October 2026", read="8 min",
  desc="The US cities where cannabis use is highest — ranked from NSDUH state surveys, dispensary-density data and market reports, from Portland's weed saturation to Oklahoma City's dispensary boom.",
  stats=[("~15,000","cannabis dispensaries across the US — 79% of Americans live in a county with at least one (Pew, 2024)"),("36","dispensaries per 100,000 residents in Oklahoma — the highest density of any state (Pew, 2024)"),("24","states where recreational cannabis is legal — plus medical in most of the rest")],
  intro="No US agency publishes a per-city weed use ranking, so this list triangulates three proxies: SAMHSA's National Survey on Drug Use and Health (which publishes state-level past-month cannabis use), dispensary counts and density (tracked by Pew Research and state regulators), and legal-market sales data. They point at a consistent map: the highest-use cities sit in the legal West and Northeast, but the most saturated retail market in the country is in medical-only Oklahoma. The ranking is directional — treat the middle of the list as a band, not an order.",
  cities=[
   ("1","Portland, OR","Oregon consistently posts among the highest past-month adult cannabis use rates in NSDUH state tables, and an early industry analysis found Oregon leading the nation in dispensaries per capita (16.5 per 100,000 residents). Cheap legal flower and a mature market keep Portland at the top of every proxy."),
   ("2","Denver, CO","The original legal-weed city (retail since 2014). Colorado remains in the top tier of NSDUH past-month use, and Denver's metro hosts hundreds of dispensaries plus the country's most established consumption culture."),
   ("3","Oklahoma City, OK","The strangest weed market in America: medical-only, but with effectively no license cap, Oklahoma reached roughly 36 dispensaries per 100,000 residents — the highest density in the nation (Pew, 2024). OKC and Tulsa anchor a market where weed is easier to buy than in most fully legal states."),
   ("4","Los Angeles, CA","Los Angeles County alone had 1,481 dispensaries at Pew's 2024 count — more than any state except California itself. Add an enormous legacy market and LA is the largest weed city in the country by sheer volume."),
   ("5","Burlington, VT","Vermont regularly tops or nears the top of NSDUH past-month use tables, especially among young adults. Burlington — a small, young, college-heavy city — concentrates that statewide pattern."),
   ("6","Seattle / Tacoma, WA","Washington legalized alongside Colorado in 2012, and the Puget Sound region shows durable top-tier use rates in federal surveys, with one of the country's densest retail networks."),
   ("7","San Francisco / Oakland, CA","The Bay Area's cannabis culture predates legalization by decades — Oakland issued the first dispensary permits in 2004. High use rates meet high prices and a still-active legacy market."),
   ("8","Detroit, MI","Michigan has grown into one of America's largest legal markets (multi-billion-dollar annual sales, among the highest per-capita in the Midwest), and Detroit's metro plus its cheap flower prices drive the state's numbers."),
   ("9","Anchorage, AK","Alaska posts some of the highest past-month use rates in NSDUH tables year after year; Anchorage holds most of the state's population and nearly all of its retail market."),
   ("10","Las Vegas, NV","A high-use resident market amplified by ~40 million tourists a year — Nevada's per-capita sales rank among the highest in the country, and dispensary density around the Strip is extreme."),
  ],
  notes="Honorable mentions: Boston and Worcester (Massachusetts' mature market), Chicago (Illinois' high-tax boom), Ann Arbor (home of Hash Bash since 1972), and Tucson/Phoenix (Arizona's fast-growing market). Notably absent: New York City — huge in absolute terms, but middling per-capita, with a legal rollout slowed by enforcement against unlicensed shops. EUDA wastewater comparisons find US and Canadian cities carry higher THC metabolite loads than even the highest European cities.",
  method="Methodology: composite of SAMHSA NSDUH state-level past-month cannabis use (most recent tables), dispensary counts and per-capita density (Pew Research 2024 analysis of state licensing data; Cannabiz Media licensing counts), and state market-sales reports. No city-level use survey exists; rankings are directional.",
  sources=["SAMHSA National Survey on Drug Use and Health (state estimates)","Pew Research Center: 'Most Americans now live in a legal marijuana state' (2024)","State cannabis regulatory sales reports (CO, OR, MI, NV, OK)","EUDA wastewater analysis — international city comparisons"]),

 dict(slug="weed-cities-canada", region="Canada", title="Top 10 Canadian cities with the most weed use",
  updated="October 2026", read="7 min",
  desc="Where weed use is highest in Canada — Halifax leads the wastewater ranking, Montreal and the BC coast follow, per Statistics Canada's wastewater pilot and National Cannabis Survey.",
  stats=[("1,310 µg","THC metabolite per person per week in Halifax wastewater — the highest of the five metros Statistics Canada tested"),("27.1 g","cannabis consumed per person per year in Nova Scotia — the highest province (StatCan National Cannabis Survey)"),("2018","Canada became the first G7 country to legalize recreational cannabis nationwide")],
  intro="Canada has something almost no other country does: a federal agency that measured city-level cannabis use in sewage. Statistics Canada's wastewater pilot tested five major metros, and its National Cannabis Survey adds provincial per-capita consumption. Together they draw a clear map — Atlantic Canada and the West Coast lead, the big Ontario and Quebec metros sit in the middle, and usage everywhere is high by global standards: European wastewater comparisons find Canadian cities' THC metabolite loads well above the highest EU cities. Treat positions 4–8 as a band.",
  cities=[
   ("1","Halifax, NS","The surprise champion: Halifax wastewater carried 1,310 micrograms of THC metabolite per person per week — the highest of any metro StatCan tested — and Nova Scotia posts the highest provincial consumption (27.1 g per person per year). A young, student-heavy city in a high-use province."),
   ("2","Montreal, QC","Second in the wastewater pilot at 976 µg per person per week — despite Quebec having the country's strictest retail rules (government stores, 21+ age limit). Montreal's huge student population keeps it near the top."),
   ("3","Victoria, BC","British Columbia ties for the highest provincial consumption outside Atlantic Canada (24.1 g per person per year), and BC survey data consistently places the capital region among the province's highest-use areas — a legacy of the coast's decades-old cannabis culture."),
   ("4","Toronto, ON","Middle of the wastewater table (451 µg) but the country's largest absolute market — Toronto's dispensary count exploded after Ontario's retail expansion, and past-year use in the metro tracks the national average of a high-use country."),
   ("5","Edmonton, AB","Close behind Toronto in the wastewater pilot (416 µg), and Alberta ties BC near the top of provincial consumption (24.6 g per person per year). Alberta also built the country's most competitive private retail market."),
   ("6","Vancouver, BC","The spiritual home of Canadian weed — but only 288 µg per person per week in the wastewater pilot, the lowest of the five metros tested. The likely explanation: BC's mature legacy market means heavy users, but the city's overall rate is diluted by demographics. Culture ≠ volume."),
   ("7","Calgary, AB","Shares Alberta's top-tier provincial numbers; Calgary and Edmonton function as one high-consumption corridor split by 300 km of highway."),
   ("8","Kelowna, BC","Interior BC posts some of the province's highest use rates in regional surveys — the Okanagan's grow-country heritage shows up in the data, and Kelowna concentrates it."),
   ("9","Ottawa, ON","National-average use but one of the country's densest dispensary maps after Ontario's open licensing — Ottawa's ByWard Market area became a notorious dispensary cluster."),
   ("10","Winnipeg, MB","Manitoba sits mid-table provincially, but Winnipeg's young demographics and harsh winters (indoor drug) keep it in the top ten across proxies."),
  ],
  notes="StatCan's wastewater pilot (2018) covered only five metros — Halifax, Montreal, Toronto, Edmonton and Vancouver — so cities beyond those rely on provincial survey data. Since legalization, national past-year use has crept upward while the legal market's share has grown past the illicit one; provincial patterns (Atlantic Canada and BC/Alberta high, Quebec mid despite strict rules) have stayed stable.",
  method="Methodology: Statistics Canada wastewater-based epidemiology pilot (THC metabolite loads, five metros, 2018), StatCan National Cannabis Survey provincial consumption estimates, and provincial retail data. Where no city measurement exists, provincial rates and market density are used as proxies. Rankings are directional.",
  sources=["Statistics Canada wastewater cannabis pilot (2018)","Statistics Canada National Cannabis Survey","EUDA wastewater analysis — international comparisons","Provincial cannabis retail sales data"]),

 dict(slug="weed-cities-europe", region="Europe", title="Top 10 European cities with the most weed use",
  updated="October 2026", read="8 min",
  desc="Europe's weed capitals measured in sewage — Dutch, German and Slovenian cities top the EUDA wastewater ranking, with Barcelona's clubs and Prague's liberal scene close behind.",
  stats=[("24M","last-year cannabis users in Europe (EUDA, 2025) — about 8.4% of adults"),("NL · DE · SI","the countries whose cities show the highest THC metabolite loads in European wastewater (EUDA 2025)"),("Stable","overall cannabis loads in European city wastewater from 2024 to 2025")],
  intro="Europe has the world's best city-level drug data: the EUDA/SCORE wastewater program tests around 130 cities in 28 countries every year, including the cannabis metabolite THC-COOH. The 2025 campaign found the highest cannabis loads in cities in the Netherlands, Germany and Slovenia — and use spread evenly across the week, unlike the weekend spiking of party drugs. National surveys add a second layer: France, Spain and Czechia post some of the highest lifetime and last-year prevalence in Europe. One caveat: THC-COOH is excreted at low and variable rates, so the wastewater ranking is noisier for cannabis than for other drugs — treat this list as a band.",
  cities=[
   ("1","Amsterdam, NL","Dutch cities top the European wastewater table, and Amsterdam remains the symbolic capital — ~170 coffeeshops plus a tourist market built on five decades of tolerance. Locals' use is high but unremarkable by Dutch standards; the tourists push the sewage numbers up."),
   ("2","Ljubljana, SI","The data's dark horse: Slovenian cities rank alongside Dutch and German ones at the top of the EUDA THC-COOH table, and Slovenia's national surveys show rising last-year use, concentrated in the young capital."),
   ("3","Berlin, DE","German cities show some of Europe's highest wastewater cannabis loads, and Berlin is the epicenter of the country's new legal reality — Germany legalized adult possession and home grow in April 2024, with cannabis social clubs licensed from July 2024."),
   ("4","Barcelona, ES","Spain's private cannabis social clubs — hundreds operate in Barcelona in a legal gray zone — make the city Europe's de-facto weed-tourism capital. Spanish surveys show among the highest last-year use in the EU."),
   ("5","Prague, CZ","Czechia consistently posts among Europe's highest prevalence in national surveys, and Prague's famously relaxed scene (possession decriminalized since 2010) makes it a perennial top-five fixture."),
   ("6","Zurich, CH","Swiss cities rank high in wastewater comparisons, and Switzerland is running the world's most advanced legal-sale pilot programs — Zurich's experiment lets registered adults buy regulated cannabis in pharmacies."),
   ("7","Copenhagen, DK","Freetown Christiania's open-air Pusher Street market operated for 50 years until residents tore it up in 2024 — but the demand it served hasn't gone anywhere, and Danish surveys keep Copenhagen in Europe's upper tier."),
   ("8","Madrid, ES","Spain's second club capital, with the country's largest population of users in absolute terms; national surveys put Spanish last-year use among young adults at the top of the EU table."),
   ("9","Paris, FR","France has among the highest lifetime cannabis use ever measured in the EU (roughly two in five adults have tried it) despite some of Europe's strictest laws — Paris concentrates that paradox."),
   ("10","Eindhoven / Tilburg, NL","The Dutch south: border-city coffeeshops serving Belgian, German and French buyers keep wastewater loads high, and Eindhoven hosts part of the Netherlands' regulated-supply experiment."),
  ],
  notes="Just outside the top ten: Rome, Brussels, Helsinki (fast-rising), and London (the UK doesn't participate in EUDA wastewater, but national surveys put British use mid-table — with a large illicit market). The big trend is regulation: Germany's legalization, Switzerland's sale pilots, the Dutch supply experiment, and Czechia's 2026 reforms are slowly converting Europe's gray markets into licensed ones.",
  method="Methodology: EUDA/SCORE wastewater analysis (THC-COOH loads, ~130 cities, 2025 campaign), EMCDDA/EUDA national survey prevalence tables, and national policy reporting. THC-COOH excretion varies between individuals, making cannabis wastewater rankings noisier than other drugs. Rankings are directional.",
  sources=["EUDA wastewater analysis — European multi-city study (2025 campaign)","EUDA European Drug Report 2025","National drug surveys (France, Spain, Czechia, Germany)","Swiss / German / Dutch regulated-market pilot reports"]),

 dict(slug="weed-cities-australia", region="Australia", title="Top 10 Australian cities with the most weed use",
  updated="October 2026", read="7 min",
  desc="Where weed use is highest in Australia — the regions out-smoke the capitals two-to-one, and Hobart leads the capital-city ranking, per the ACIC national wastewater program.",
  stats=[("~2×","regional Australia's average cannabis consumption compared with the capital cities (ACIC wastewater)"),("#1","Hobart records the highest cannabis consumption of any Australian capital city"),("Most-used","illicit drug in Australia — cannabis outranks every other illicit substance in every jurisdiction")],
  intro="Australia measures drugs in sewage better than almost anyone: the ACIC National Wastewater Drug Monitoring Program covers more than half the population across ~50 sites. Its cannabis finding is remarkably stable — consumption in regional Australia runs about double the capital-city average, regional sites in the Northern Territory, South Australia and Western Australia are consistently highest, and Hobart leads the capitals. Cannabis remains the most-consumed illicit drug in the country by a wide margin. Capital-city figures below combine wastewater with the National Drug Strategy Household Survey; treat the middle of the list as a band.",
  cities=[
   ("1","Hobart, TAS","The highest cannabis consumption of any Australian capital in the wastewater program — Tasmania's capital has led the city table across multiple reporting periods, with a stable, older-using, home-grow culture."),
   ("2","Darwin, NT","The NT's regional sites post among the highest cannabis loads in the country, and Darwin combines those territory-wide patterns with the highest alcohol and nicotine consumption in the program — a heavy-use town by every measure."),
   ("3","Adelaide, SA","South Australia pairs the highest regional cannabis consumption in the country with a mid-table capital — and SA's long-expiation (decriminalized fines) history means Adelaide's use is stable and unremarkable to locals."),
   ("4","Regional NT / Alice Springs","The top of the national table isn't a capital: regional Northern Territory sites record the country's highest per-capita cannabis consumption, with Alice Springs the hub."),
   ("5","Regional SA (Whyalla / Mt Gambier)","Regional South Australia ties the NT at the top of the wastewater table — small industrial towns with some of the highest measured per-capita use in Australia."),
   ("6","Perth, WA","WA's regional sites round out the 'highest three' jurisdictions, and Perth sits at the top of the big-city band — above Sydney and Melbourne in the wastewater data."),
   ("7","Cairns / Townsville, QLD","Regional Queensland runs well above the capital-city average; the far-north towns combine remote-area consumption patterns with a long grow-country history in the hinterland."),
   ("8","Canberra, ACT","The only Australian jurisdiction where adult possession and home-grow are legal (since 2020, 50 g / two plants). Measured consumption is mid-table — legalization here changed the law more than the behavior."),
   ("9","Byron Bay, NSW","Australia's counterculture capital: the Northern Rivers region has been grow country since the 1970s, and Byron's per-capita use outranks every NSW city — though Sydney's wastewater stays low."),
   ("10","Brisbane, QLD","The largest of the mid-table capitals: below Hobart and Perth, around the national capital average, and steadily rising with Queensland's population boom."),
  ],
  notes="Sydney and Melbourne — the biggest cities — consistently record the LOWEST capital-city cannabis consumption in the wastewater program. That's the Australian pattern in one line: weed is a regional and small-city drug, while the big eastern capitals run on cocaine. Medicinal cannabis (legal federally since 2016, prescribed widely since 2022) now adds a fast-growing legal stream the wastewater can't distinguish from illicit use.",
  method="Methodology: ACIC National Wastewater Drug Monitoring Program (reports 22–25, THC-COOH loads by site), National Drug Strategy Household Survey, and published analysis of ACIC data (2018–2025 trends). Regional vs capital comparisons are population-normalized. Rankings are directional.",
  sources=["ACIC National Wastewater Drug Monitoring Program (reports 22–25)","AIHW National Drug Strategy Household Survey","Published wastewater trend analysis, cannabis in Australia 2018–2025 (Addiction)","ACT cannabis legislation review"]),

 dict(slug="weed-cities-middle-east", region="Middle East", title="Top 10 Middle Eastern cities with the most weed use",
  updated="October 2026", read="7 min",
  desc="Weed in the Middle East — Israel's high-prevalence cities, Lebanon's hashish heartland in the Bekaa, and the region's slow shift from prohibition to medical programs.",
  stats=[("Top-tier","Israel posts among the highest national past-year cannabis prevalence measured anywhere (national surveys)"),("2020","Lebanon became the first Arab country to legalize cannabis cultivation (medical/industrial)"),("Bekaa","Lebanon's Bekaa Valley is one of the world's oldest and largest hashish-producing regions")],
  intro="No Middle Eastern country publishes city-level cannabis data, and most governments underreport use — so this ranking leans on three proxies: Israel's unusually good national survey data, UNODC World Drug Report country estimates, and the production geography of hashish (Lebanon's Bekaa Valley, with Turkish and Egyptian transit and consumption markets). The headline: the Middle East's weed capital is Tel Aviv by use, Baalbek by production. Everywhere else, harsh laws push the market underground — treat this entire list as an informed estimate.",
  cities=[
   ("1","Tel Aviv, IL","Israel's national surveys put past-year cannabis use at the top of international comparisons (around one in four adults in some waves), and Tel Aviv — young, secular, nightlife-dense — concentrates it. Israel also runs one of the world's largest medical cannabis programs (~100,000 licensed patients)."),
   ("2","Baalbek / Hermel, LB","The capital of the Bekaa Valley's hashish industry — thousands of hectares of cannabis cultivated openly in defiance of, then under the umbrella of, Lebanon's 2020 cultivation law. Production, not consumption, ranks it here."),
   ("3","Beirut, LB","Lebanon's consumption capital: hash is cheap, locally produced and socially normalized across much of Beirut despite formal prohibition, and the economic collapse made it cheaper still."),
   ("4","Jerusalem / Haifa, IL","Israel's other major cities track Tel Aviv's national-level prevalence a notch lower; Haifa's port keeps supply easy."),
   ("5","Istanbul, TR","Türkiye is a transit corridor for Afghan hashish and a producer in its own southeast; Istanbul's 16 million people make it the region's largest absolute consumer market, with use concentrated in nightlife districts."),
   ("6","Tehran, IR","Iran's drug data focuses on opiates, but hashish flows west from Afghanistan through the capital; treatment-system reporting shows cannabis the most-used illicit drug after opiates among young Tehranis."),
   ("7","Cairo, EG","Egypt's hashish market (supplied via the Sinai and Sudan routes) is centuries old and enormous in absolute terms; 'bango' (local herbal cannabis) is grown in Upper Egypt and the Sinai."),
   ("8","Amman, JO","Jordan is mostly a transit country (Captagon north, hashish south), but Amman's young, urban population drives the region's second tier of consumption."),
   ("9","Dubai, AE","Tiny prevalence but wealthy demand — the Gulf's strictest laws (residue-level prosecutions, though softened in 2021) suppress a market that persists among expatriates and the party circuit."),
   ("10","Ramallah / West Bank","Palestinian surveys are sparse, but hashish use in the West Bank is documented and rising, supplied through the same Israeli market that tops this list."),
  ],
  notes="The structural trend: medical programs are the thin end of the wedge. Israel's is huge, Lebanon legalized cultivation (2020), and Türkiye legalized medical production — while the Gulf states keep near-zero tolerance. UNODC estimates for the region are among the world's least reliable; every ranking here should be read as approximate.",
  method="Methodology: Israeli national drug surveys and medical-program licensing data, UNODC World Drug Report country estimates, Lebanese cultivation-law reporting, and regional seizure/transit analysis. No city-level measurement exists anywhere in the region. Rankings are directional estimates.",
  sources=["Israel Ministry of Health — national drug use surveys and medical cannabis program data","UNODC World Drug Report","Lebanon cannabis cultivation law reporting (2020)","EMCDDA/EUDA regional analyses"]),

 dict(slug="weed-cities-africa", region="Africa", title="Top 10 African cities with the most weed use",
  updated="October 2026", read="7 min",
  desc="Africa's weed map — Nigeria's world-leading prevalence, South Africa's legal private market, and Morocco's Rif, from Lagos to Cape Town, per UNODC data.",
  stats=[("10.8%","past-year cannabis prevalence among Nigerian adults — among the highest national rates ever measured (UNODC-supported 2018 survey)"),("2024","South Africa's Cannabis for Private Purposes Act signed — Africa's first legal private-use framework"),("Rif","Morocco's Rif mountains remain one of the world's largest cannabis-resin (hashish) producing regions")],
  intro="Africa has the world's fastest-growing cannabis population and some of its least precise data. The landmarks: a 2018 UNODC-supported national survey found Nigeria's past-year prevalence at 10.8% — among the highest ever measured in any country; South Africa's Constitutional Court decriminalized private adult use in 2018 and parliament completed the framework in 2024; and Morocco — the historic supplier of Europe's hashish — legalized medical and industrial cultivation in 2021. City rankings combine those national anchors with treatment and seizure reporting. Every position here is an informed estimate.",
  cities=[
   ("1","Lagos, NG","The megacity at the center of the world's highest-prevalence national market: Nigeria's 10.8% past-year rate translates to tens of millions of users, and Lagos — 20+ million people — is both the biggest consumption and the biggest distribution hub in West Africa."),
   ("2","Johannesburg, ZA","South Africa's commercial capital runs Africa's most formalized weed economy — private clubs and 'dispensary-style' gray-market shops multiplied after the 2018 court ruling, years before the 2024 Act clarified the rules."),
   ("3","Cape Town, ZA","The counterculture and cultivation capital: the Western Cape's grow regions supply the country, Cape Town's ' cannabis cup' scene is the continent's most visible, and use rates in the metro lead national surveys."),
   ("4","Chefchaouen / Al Hoceima, MA","The heart of the Rif — towns whose entire economy ran on kif for a century. Legalization (2021) moved production toward licensed cooperatives, but the Rif remains the supply engine for Europe's hashish market."),
   ("5","Durban, ZA","Home of 'Durban Poison' — one of the world's most famous landrace strains — and South Africa's third major consumption market, with KwaZulu-Natal's rural grow regions behind it."),
   ("6","Nairobi, KE","East Africa's biggest consumer market: Kenyan surveys show rising urban youth use, and Nairobi's 'bhang' trade (plus smuggled Ethiopian and Tanzanian highland product) supplies it."),
   ("7","Accra, GH","Ghana passed a limited THC-threshold licensing law in 2020 (Narcotics Control Commission Act) after years of de-facto tolerance; Accra's youth market is West Africa's second most visible after Lagos."),
   ("8","Abuja / Port Harcourt, NG","Nigeria's second tier — the federal capital and the oil hub both show high use in the national survey's state breakdowns."),
   ("9","Addis Ababa, ET","Ethiopia grows and consumes chat legally, but cannabis ('dagga') use in the capital is documented and climbing, supplied by the country's southern highlands."),
   ("10","Dakar, SN","Senegal's capital anchors a coastal West African consumption belt (Casamance-grown 'yamba'), with use normalized in parts of the music and fishing communities."),
  ],
  notes="The continental trend is reform: South Africa (2024), Morocco (2021), Ghana (2020), Zimbabwe and Lesotho (medical/export licensing), Malawi (2020 industrial) and Rwanda have all moved, driven partly by the export economics of medical cannabis. UNODC estimates African users will grow faster than any other region through 2030 — but data quality means every ranking here is approximate.",
  method="Methodology: UNODC World Drug Report regional estimates, the UNODC-supported Nigeria national drug use survey (2018), South African legal-market reporting, and treatment/seizure data from national drug agencies. No city-level measurement exists on the continent. Rankings are directional estimates.",
  sources=["UNODC World Drug Report","Nigeria National Drug Use Survey 2018 (UNODC/EU-supported)","South Africa Cannabis for Private Purposes Act (2024) and market reporting","Morocco cannabis legalization reporting (2021)"]),
]
